const $=id=>document.getElementById(id),key='arnes-providers-v1';let catalog=[],detected=[],settings={},active='dashboard',detectionNote='',snapshotDate='publication',reports={},reportTime='',reportError='';
try{const saved=JSON.parse(localStorage.getItem(key));if(saved&&typeof saved==='object'&&!Array.isArray(saved))settings=saved;}catch{}
const consoles={thinkingmachines:'https://tinker-console.thinkingmachines.ai/keys',huggingface:'https://huggingface.co/settings/tokens','github-copilot':'https://github.com/settings/tokens',nvidia:'https://build.nvidia.com/settings/api-keys',openai:'https://platform.openai.com/api-keys',anthropic:'https://console.anthropic.com/settings/keys',google:'https://aistudio.google.com/apikey',openrouter:'https://openrouter.ai/settings/keys',groq:'https://console.groq.com/keys',deepseek:'https://platform.deepseek.com/api_keys',mistral:'https://console.mistral.ai/api-keys',togetherai:'https://api.together.ai/settings/api-keys',fireworks:'https://fireworks.ai/account/api-keys',cerebras:'https://cloud.cerebras.ai/platform',xai:'https://console.x.ai',cohere:'https://dashboard.cohere.com/api-keys', 'moonshotai':'https://platform.moonshot.ai/console/api-keys'};
function safeUrl(raw){const u=new URL(raw);if(!['https:','http:'].includes(u.protocol)||u.username||u.password)throw Error('Use an HTTP or HTTPS URL without credentials.');return u.href;}
function configured(p){return detected.includes(p.id)||settings[p.id]?.configured===true;}
function consoleUrl(p){try{return safeUrl(settings[p.id]?.url||consoles[p.id]||'');}catch{return '';}}
function save(){try{localStorage.setItem(key,JSON.stringify(settings));return true;}catch{$('status').textContent='Browser storage is unavailable. Changes last for this visit.';return false;}}
function el(tag,text,cls){const e=document.createElement(tag);if(text!=null)e.textContent=text;if(cls)e.className=cls;return e;}
function select(id){active=id;renderTabs();$('dashboard').hidden=id!=='dashboard';$('console').hidden=id==='dashboard';if(id==='dashboard')return;const p=catalog.find(p=>p.id===id);if(!p)return select('dashboard');$('console-name').textContent=p.name;const url=consoleUrl(p);for(const link of [$('open'),$('launch')]){link.hidden=!url;if(url)link.href=url;else link.removeAttribute('href');}$('launch-title').textContent=p.name+' console';$('launch-note').textContent=url?'Open the provider’s own site to manage API keys, usage and billing. Sign in there with your existing account.':'Add your API management address using Change URL.';$('console-address').textContent=url;$('provider-model-search').value='';renderProviderModels();renderProviderReport();}
function renderProviderModels(){const p=catalog.find(p=>p.id===active);if(!p)return;const q=$('provider-model-search').value.trim().toLowerCase();const models=p.models.filter(m=>(m.name+' '+m.id).toLowerCase().includes(q));$('provider-model-count').textContent=models.length.toLocaleString()+' catalog models';const list=$('provider-models');list.replaceChildren();for(const m of models){const row=el('div',null,'model');row.append(el('span',m.name),el('code',m.id+(m.context?' · '+m.context.toLocaleString()+' context':'')));list.append(row);}if(!models.length)list.append(el('p','No matching catalog models.'));}
function renderTabs(){const nav=$('tabs');nav.replaceChildren();for(const p of [{id:'dashboard',name:'Dashboard'},...catalog.filter(configured)]){const b=el('button',p.name);b.type='button';b.role='tab';b.setAttribute('aria-selected',String(active===p.id));b.onclick=()=>select(p.id);nav.append(b);}}
function changeUrl(p){const raw=prompt('API management page URL for '+p.name,consoleUrl(p));if(raw===null)return;try{settings[p.id]={...settings[p.id],url:safeUrl(raw)};save();if(active===p.id)select(p.id);}catch(e){alert(e.message);}}
function renderCards(){const q=$('search').value.trim().toLowerCase(),only=$('configured-only').checked;const rows=catalog.filter(p=>(!only||configured(p))&&(!q||(p.name+' '+p.id).toLowerCase().includes(q)||p.models.some(m=>(m.name+' '+m.id).toLowerCase().includes(q))));$('cards').replaceChildren();for(const p of rows){const c=el('article',null,'card'),h=el('div',null,'card-head');h.append(el('h2',p.name),el('span',detected.includes(p.id)?'Detected locally':configured(p)?'Configured · marked manually':'Not configured','badge'+(configured(p)?' configured':'')));c.append(h);const d=el('details');const matches=(p.name+' '+p.id).toLowerCase().includes(q)?p.models:p.models.filter(m=>(m.name+' '+m.id).toLowerCase().includes(q));d.append(el('summary',matches.length.toLocaleString()+' models'));const list=el('div',null,'models');d.addEventListener('toggle',()=>{if(!d.open||list.childElementCount)return;for(const m of matches){const row=el('div',null,'model');row.append(el('span',m.name),el('code',m.id+(m.context?' · '+m.context.toLocaleString()+' context':'')));list.append(row);}});d.append(list);c.append(d);const actions=el('div',null,'card-actions');if(configured(p)){const b=el('button','API management ↗');b.onclick=()=>select(p.id);actions.append(b);}const toggle=el('button',configured(p)?'Remove manual configuration':'Mark configured');toggle.disabled=detected.includes(p.id);toggle.title=toggle.disabled?'Detected from local credentials. Manage credentials in the source application.':'This tracks an existing account; it does not create or validate API credentials.';toggle.onclick=()=>{settings[p.id]={...settings[p.id],configured:!configured(p)};save();render();};actions.append(toggle);const edit=el('button','Console URL');edit.onclick=()=>changeUrl(p);actions.append(edit);c.append(actions);$('cards').append(c);}if(!rows.length)$('cards').append(el('p','No matching providers or models.'));$('status').textContent=rows.length+' providers shown. '+detectionNote;}
function render(){renderTabs();$('stats').replaceChildren();for(const [label,value]of [['Providers',catalog.length],['Models',catalog.reduce((s,p)=>s+p.models.length,0)],['Configured',catalog.filter(configured).length]]){const c=el('div',null,'stat');c.append(el('span',label),el('strong',value.toLocaleString()));$('stats').append(c);}renderCards();renderReports();}
async function refresh(){ $('refresh').disabled=true;try{const r=await fetch('/hub/providers/configuration',{cache:'no-store'});if(!r.ok)throw Error();const d=await r.json();detected=Array.isArray(d.configured)?d.configured:[];detectionNote='Local credential presence checked; account access is not validated.';}catch{detectionNote='Showing the local configuration snapshot from '+snapshotDate+'. Open the private Tailscale workspace to refresh detected credentials.';}finally{await refreshMetrics();$('refresh').disabled=false;render();if(active!=='dashboard'&&!catalog.some(p=>p.id===active&&configured(p)))select('dashboard');}}
$('provider-model-search').oninput=renderProviderModels;$('search').oninput=renderCards;$('configured-only').onchange=renderCards;$('refresh').onclick=refresh;$('change').onclick=()=>changeUrl(catalog.find(p=>p.id===active));
(async()=>{try{const r=await fetch('providers-catalog.json');if(!r.ok)throw Error();const d=await r.json();detected=d.configurationSnapshot?.configured||[];snapshotDate=new Date(d.configurationSnapshot?.checkedAt||d.updatedAt).toLocaleString();catalog=d.providers.sort((a,b)=>a.name.localeCompare(b.name));$('source').append(document.createTextNode('Catalog snapshot '+new Date(d.updatedAt).toLocaleDateString()+' · '));const a=el('a','Models.dev');a.href=d.source;a.target='_blank';a.rel='noopener noreferrer';$('source').append(a,document.createTextNode(' · Catalog models may differ from your account access. Configuration markers and console URLs are saved in this browser.'));await refresh();}catch{$('status').textContent='The provider catalog could not load. Reload to retry.';}})();

function reportFor(p){return reports[p.id]||{state:'unavailable',note:reportError||'Account-wide balance and usage reporting is not integrated for this provider. Use its console for billing details.',metrics:[]};}
function reportPanel(p){const d=reportFor(p),panel=el('article',null,'usage-report');panel.append(el('h2',p.name),el('span',d.state==='live'?'Live API report':d.state==='needs_admin'?'Admin key required':d.state==='error'?'Report unavailable':'No report available','badge'));const grid=el('div',null,'metric-grid');for(const m of d.metrics||[]){const card=el('div',null,'stat');const value=typeof m.value==='number'&&Number.isFinite(m.value)?new Intl.NumberFormat(undefined,{style:'currency',currency:m.currency||'USD',maximumFractionDigits:4}).format(m.value):'Unavailable';card.append(el('span',m.label),el('strong',value));grid.append(card);}panel.append(grid,el('p',d.note));return panel;}
function renderProviderReport(){const p=catalog.find(p=>p.id===active);if(!p)return;$('provider-metrics').replaceChildren(reportPanel(p));}
function renderReports(){const list=$('metrics-overview');list.replaceChildren();for(const p of catalog.filter(configured))list.append(reportPanel(p));if(!list.childElementCount)list.append(el('p','Mark providers configured to see their reporting support.'));$('metrics-status').textContent=reportError||('Checked '+new Date(reportTime).toLocaleString()+' · reports refresh at most once per minute.');$('private-data').hidden=!reportError;if(active!=='dashboard')renderProviderReport();}
async function refreshMetrics(){try{const host=location.hostname,url=['127.0.0.1','localhost','hub.example.invalid'].includes(host)?'/hub/providers/metrics':'https://hub.example.invalid/hub/providers/metrics';const r=await fetch(url,{cache:'no-store',signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error();const data=await r.json();reports=data.providers||{};reportTime=data.checkedAt;reportError='';}catch{reports={};reportError='Live reports require access to your private Tailnet workspace. No balances are stored in this hosted site.';}renderReports();}
